// same-thread ring in a fixed, known memory footprint (audio worklet / telemetry):
class Ring {
    constructor(sizePow2) {           // power of two: the wrap is a mask
        this.buf = new Float32Array(sizePow2);   // fixed memory, no GC churn
        this.mask = sizePow2 - 1;
        this.head = 0; this.tail = 0;
    }
    push(v) {
        const next = (this.head + 1) & this.mask;
        if (next === this.tail) return false;      // full (one slot wasted)
        this.buf[this.head] = v;
        this.head = next;
        return true;
    }
    pop() {
        if (this.tail === this.head) return undefined;
        const v = this.buf[this.tail];
        this.tail = (this.tail + 1) & this.mask;
        return v;
    }
}
// across workers: SharedArrayArray + Atomics for the indices; note
// Atomics.wait throws on the main thread, so the main thread polls.
